#include <unordered_map>
#include <algorithm>

class Solution {
    std::unordered_map<int, int> memo;
public:
    int minDaysToScore(int n) {
        if (n <= 1) return n;
        if (memo.count(n)) return memo[n];

        int res = n;
        res = std::min(res, 1 + (n % 2) + minDaysToScore(n / 2));
        res = std::min(res, 1 + (n % 3) + minDaysToScore(n / 3));
        return memo[n] = res;
    }
};

import java.util.*;

class Solution {
    private Map<Integer, Integer> memo = new HashMap<>();

    public int minDaysToScore(int n) {
        if (n <= 1) return n;
        if (memo.containsKey(n)) return memo.get(n);

        int res = n;
        res = Math.min(res, 1 + (n % 2) + minDaysToScore(n / 2));
        res = Math.min(res, 1 + (n % 3) + minDaysToScore(n / 3));
        memo.put(n, res);
        return res;
    }
}

function minDaysToScore(n) {
    const memo = new Map();

    function solve(target) {
        if (target <= 1) return target;
        if (memo.has(target)) return memo.get(target);

        let res = target;
        res = Math.min(res, 1 + (target % 2) + solve(Math.floor(target / 2)));
        res = Math.min(res, 1 + (target % 3) + solve(Math.floor(target / 3)));
        memo.set(target, res);
        return res;
    }

    return solve(n);
}
